// Safe localStorage and sessionStorage shims shadowing standard globals to avoid SecurityError inside iframe sandbox
const localStorage = (typeof window !== "undefined" && (window as any).safeLocalStorage) || {
  getItem: () => null,
  setItem: () => {},
  removeItem: () => {},
  clear: () => {},
  key: () => null,
  length: 0
};
const sessionStorage = (typeof window !== "undefined" && (window as any).safeSessionStorage) || {
  getItem: () => null,
  setItem: () => {},
  removeItem: () => {},
  clear: () => {},
  key: () => null,
  length: 0
};

/**
 * Validate an audio source (Archive.org or Custom URL) using a HEAD request.
 * Checks for 503/404 availability, and automatically switches to the secondary URL if the primary fails.
 */
export async function validateAudioSource(
  primaryUrl: string, 
  secondaryUrl?: string
): Promise<{ 
  url: string; 
  isFallback: boolean; 
  success: boolean; 
  errorType?: "404_ERROR" | "FORMAT_ERROR" | "NETWORK_ERROR" | null;
  message?: string;
}> {
  type CheckResult = { 
    success: boolean; 
    status: "ok" | "error" | "network_error"; 
    errorType?: "404_ERROR" | "FORMAT_ERROR" | "NETWORK_ERROR" | null;
  };

  const normalizeUrl = (u: string): string => {
    if (!u) return "";
    let decoded = u.trim();
    if (decoded.includes("archive.org/download/")) {
      decoded = decoded.replace("archive.org/download/", "archive.org/cors/");
    }
    return decoded;
  };

  const normalizedPrimary = normalizeUrl(primaryUrl);
  const normalizedSecondary = secondaryUrl ? normalizeUrl(secondaryUrl) : undefined;

  // Prioritize Headless check via Service Worker message
  const checkViaServiceWorker = (url: string): Promise<CheckResult | null> => {
    return new Promise((resolve) => {
      if (typeof navigator === "undefined" || !navigator.serviceWorker || !navigator.serviceWorker.controller) {
        return resolve(null);
      }
      try {
        const channel = new MessageChannel();
        channel.port1.onmessage = (event) => {
          if (event.data) {
            resolve({
              success: event.data.success,
              status: event.data.success ? "ok" : "error",
              errorType: event.data.errorType
            });
          } else {
            resolve(null);
          }
        };
        navigator.serviceWorker.controller.postMessage(
          { type: "VALIDATE_URL", url },
          [channel.port2]
        );
        // Timeout after 1500ms to ensure non-blocking
        setTimeout(() => resolve(null), 1500);
      } catch (err) {
        resolve(null);
      }
    });
  };

  const checkUrl = async (urlToCheck: string): Promise<CheckResult> => {
    if (!urlToCheck) return { success: false, status: "error", errorType: "404_ERROR" };
    
    // 1. Try Service Worker Headless check first
    const swResult = await checkViaServiceWorker(urlToCheck);
    if (swResult) {
      console.log(`[validateAudioSource] Prioritized Service Worker headless validation result:`, swResult);
      return swResult;
    }

    let has404 = false;
    let hasFormatError = false;
    let has503OrTransient = false;

    const inspectResponse = (status: number, headers: Headers | null) => {
      if (status === 404) {
        has404 = true;
      }
      if (status === 503 || status >= 500) {
        has503OrTransient = true;
      }
      if (headers) {
        const contentType = headers.get("content-type") || "";
        const isAudio = !contentType || contentType.includes("audio") || contentType.includes("octet-stream") || contentType.includes("video") || contentType.includes("audio/mpeg") || contentType.includes("audio/ogg") || contentType.includes("audio/wav");
        if (contentType && !isAudio && (contentType.includes("text/html") || contentType.includes("application/json") || contentType.includes("text/plain"))) {
          hasFormatError = true;
        }
      }
    };

    // 2. Direct HEAD check
    try {
      const directResponse = await fetch(urlToCheck, { method: "HEAD" });
      inspectResponse(directResponse.status, directResponse.headers);
      if (directResponse.status >= 200 && directResponse.status < 400 && !hasFormatError) {
        return { success: true, status: "ok" };
      }
      console.log(`[validateAudioSource] Direct HEAD check status: ${directResponse.status}, continuing checks...`);
    } catch (directErr) {
      console.log(`[validateAudioSource] Direct HEAD request failed or blocked by CORS.`);
    }

    // 3. Try checking via our audio proxy using HEAD request
    try {
      const proxyUrl = `/api/audio-proxy?url=${encodeURIComponent(urlToCheck)}`;
      const proxyResponse = await fetch(proxyUrl, { method: "HEAD" });
      inspectResponse(proxyResponse.status, proxyResponse.headers);
      if (proxyResponse.status >= 200 && proxyResponse.status < 400 && !hasFormatError) {
        return { success: true, status: "ok" };
      }
      console.log(`[validateAudioSource] Proxy HEAD check status: ${proxyResponse.status}, continuing checks...`);
    } catch (proxyErr) {
      console.log(`[validateAudioSource] Proxy HEAD request failed:`, proxyErr);
    }

    // 4. Direct GET Range fallback (some servers block HEAD/CORS but allow partial GET)
    try {
      const directGetResponse = await fetch(urlToCheck, {
        method: "GET",
        headers: { "Range": "bytes=0-0" }
      });
      inspectResponse(directGetResponse.status, directGetResponse.headers);
      if (directGetResponse.status >= 200 && directGetResponse.status < 400 && !hasFormatError) {
        return { success: true, status: "ok" };
      }
      console.log(`[validateAudioSource] Direct GET check status: ${directGetResponse.status}, continuing checks...`);
    } catch (getErr) {
      console.log(`[validateAudioSource] Direct GET request failed/CORS-blocked.`);
    }

    // 5. Proxy GET Range fallback
    try {
      const proxyUrl = `/api/audio-proxy?url=${encodeURIComponent(urlToCheck)}`;
      const proxyGetResponse = await fetch(proxyUrl, {
        method: "GET",
        headers: { "Range": "bytes=0-0" }
      });
      inspectResponse(proxyGetResponse.status, proxyGetResponse.headers);
      if (proxyGetResponse.status >= 200 && proxyGetResponse.status < 400 && !hasFormatError) {
        return { success: true, status: "ok" };
      }
      console.log(`[validateAudioSource] Proxy GET check status: ${proxyGetResponse.status}`);
    } catch (proxyGetErr) {
      console.log(`[validateAudioSource] Proxy GET request failed:`, proxyGetErr);
      return { success: false, status: "network_error", errorType: "NETWORK_ERROR" };
    }

    if (has404) {
      return { success: false, status: "error", errorType: "404_ERROR" };
    }
    if (hasFormatError) {
      return { success: false, status: "error", errorType: "FORMAT_ERROR" };
    }
    if (has503OrTransient) {
      return { success: false, status: "network_error", errorType: "NETWORK_ERROR" };
    }
    return { success: false, status: "network_error", errorType: null };
  };

  console.log(`[validateAudioSource] Checking primary URL: ${normalizedPrimary}`);
  const primaryResult = await checkUrl(normalizedPrimary);
  if (primaryResult.success) {
    return { url: normalizedPrimary, isFallback: false, success: true };
  }

  // If primary failed, attempt validation of secondary
  if (normalizedSecondary && normalizedSecondary !== normalizedPrimary) {
    console.log(`[validateAudioSource] Primary URL validation failed (status: ${primaryResult.status}, type: ${primaryResult.errorType}). Trying secondary URL: ${normalizedSecondary}`);
    const secondaryResult = await checkUrl(normalizedSecondary);
    if (secondaryResult.success) {
      console.log(`[validateAudioSource] Secondary URL is valid. Failover successful.`);
      return { url: normalizedSecondary, isFallback: true, success: true };
    }
    
    // If secondary also failed, decide based on failure types
    if (primaryResult.status === "network_error" || secondaryResult.status === "network_error") {
      console.log(`[validateAudioSource] Both failed but at least one was a network/CORS error. Defaulting to primary without disabling playback.`);
      return { 
        url: normalizedPrimary, 
        isFallback: false, 
        success: true, 
        errorType: "NETWORK_ERROR",
        message: "Transient network issue detected. Redundant proxies active."
      };
    }
  } else {
    // No secondary URL, but if primary failed due to network_error, default to true rather than locking user out
    if (primaryResult.status === "network_error") {
      return { 
        url: normalizedPrimary, 
        isFallback: false, 
        success: true, 
        errorType: "NETWORK_ERROR",
        message: "Stream is un-validated due to network/CORS boundary, attempting playback anyway."
      };
    }
  }

  console.error(`[validateAudioSource] All available URLs failed validation. Alerting offline status.`);
  
  let friendlyMessage = "The audio stream is currently offline or unreachable.";
  if (primaryResult.errorType === "404_ERROR") {
    friendlyMessage = "Format or File Missing (404 Error): The audio file is no longer available on the remote server.";
  } else if (primaryResult.errorType === "FORMAT_ERROR") {
    friendlyMessage = "Mismatched Format: The server returned an HTML error webpage or invalid media encoding instead of raw playable audio.";
  }

  return { 
    url: normalizedPrimary, 
    isFallback: false, 
    success: false, 
    errorType: primaryResult.errorType,
    message: friendlyMessage
  };
}

// Helper functions to safely query, request, and send browser Push Notifications inside a sandboxed cross-origin iframe context without throwing security exceptions.
export function getSafeNotificationPermission(): NotificationPermission {
  if (typeof window !== "undefined" && "Notification" in window) {
    try {
      return Notification.permission;
    } catch (e) {
      console.warn("Notification permission check blocked by iframe sandboxing policy:", e);
    }
  }
  return "default";
}

export async function requestSafeNotificationPermission(): Promise<NotificationPermission> {
  if (typeof window !== "undefined" && "Notification" in window) {
    try {
      return await Notification.requestPermission();
    } catch (e) {
      console.warn("Notification permission request blocked by iframe sandboxing policy:", e);
    }
  }
  return "default";
}

export function sendSafeNotification(title: string, options?: NotificationOptions) {
  if (typeof window !== "undefined" && "Notification" in window) {
    try {
      if (getSafeNotificationPermission() === "granted") {
        new Notification(title, options);
      }
    } catch (e) {
      console.warn("Notification delivery blocked or failed in current frame context:", e);
    }
  }
}

export function getSafeSpeechSynthesis(): SpeechSynthesis | null {
  if (typeof window !== "undefined") {
    try {
      if ("speechSynthesis" in window) {
        return window.speechSynthesis;
      }
    } catch (e) {
      console.warn("SpeechSynthesis access blocked by sandboxing or security policy:", e);
    }
  }
  return null;
}

// --- IndexedDB Caching Layer for Audio Streams with Auto-Prune (500MB Limit) ---
const openAudioDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    try {
      const request = indexedDB.open("AudioCacheDB", 1);
      request.onupgradeneeded = () => {
        const db = request.result;
        if (!db.objectStoreNames.contains("audio-streams")) {
          db.createObjectStore("audio-streams");
        }
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    } catch (e) {
      reject(e);
    }
  });
};

interface AudioCacheMeta {
  timestamp: number;
  size: number;
}

type AudioCacheMetadataMap = Record<string, AudioCacheMeta>;

const CACHE_MAX_SIZE_BYTES = 500 * 1024 * 1024; // 500MB Limit

export const getAudioCacheMetadata = (): AudioCacheMetadataMap => {
  if (typeof window === "undefined") return {};
  try {
    const raw = localStorage.getItem("scripture_audio_cache_metadata");
    return raw ? JSON.parse(raw) : {};
  } catch (e) {
    return {};
  }
};

const saveAudioCacheMetadata = (metadata: AudioCacheMetadataMap) => {
  if (typeof window === "undefined") return;
  try {
    localStorage.setItem("scripture_audio_cache_metadata", JSON.stringify(metadata));
  } catch (e) {}
};

export const syncAudioCacheMetadata = async (): Promise<AudioCacheMetadataMap> => {
  const actualKeys = await getAllCachedAudioKeys();
  const currentMeta = getAudioCacheMetadata();
  const updatedMeta: AudioCacheMetadataMap = {};
  
  for (const key of actualKeys) {
    if (currentMeta[key]) {
      updatedMeta[key] = currentMeta[key];
    } else {
      updatedMeta[key] = {
        timestamp: Date.now(),
        size: 0
      };
    }
  }
  
  saveAudioCacheMetadata(updatedMeta);
  return updatedMeta;
};

export const updateAudioCacheMetadata = async (key: string, size: number, updateTimestamp = true): Promise<void> => {
  const meta = getAudioCacheMetadata();
  const prev = meta[key];
  meta[key] = {
    timestamp: updateTimestamp ? Date.now() : (prev?.timestamp || Date.now()),
    size: size
  };
  saveAudioCacheMetadata(meta);
};

export const pruneAudioCacheIfNeeded = async (): Promise<void> => {
  await syncAudioCacheMetadata();
  const meta = getAudioCacheMetadata();
  
  let totalSize = Object.values(meta).reduce((sum, item) => sum + item.size, 0);
  if (totalSize <= CACHE_MAX_SIZE_BYTES) {
    return;
  }
  
  console.log(`[Audio Cache Manager] Total cache size of ${(totalSize / (1024 * 1024)).toFixed(2)}MB exceeds 500MB limit. Pruning oldest items...`);
  
  const sortedKeys = Object.keys(meta).sort((a, b) => meta[a].timestamp - meta[b].timestamp);
  
  for (const key of sortedKeys) {
    if (totalSize <= CACHE_MAX_SIZE_BYTES) {
      break;
    }
    
    const itemSize = meta[key]?.size || 0;
    console.log(`[Audio Cache Manager] Auto-pruning oldest cached audio: "${key}" (Size: ${(itemSize / (1024 * 1024)).toFixed(2)}MB)`);
    
    try {
      const db = await openAudioDB();
      await new Promise<void>((resolve, reject) => {
        try {
          const transaction = db.transaction("audio-streams", "readwrite");
          const store = transaction.objectStore("audio-streams");
          const request = store.delete(key);
          request.onsuccess = () => resolve();
          request.onerror = () => reject(request.error);
        } catch (e) {
          reject(e);
        }
      });
      
      delete meta[key];
      totalSize -= itemSize;
    } catch (e) {
      console.error(`Failed to auto-prune key "${key}":`, e);
    }
  }
  
  saveAudioCacheMetadata(meta);
};

export const cacheAudioStream = async (key: string, blob: Blob): Promise<void> => {
  const db = await openAudioDB();
  await new Promise<void>((resolve, reject) => {
    try {
      const transaction = db.transaction("audio-streams", "readwrite");
      const store = transaction.objectStore("audio-streams");
      const request = store.put(blob, key);
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    } catch (e) {
      reject(e);
    }
  });
  
  await updateAudioCacheMetadata(key, blob.size, true);
  await pruneAudioCacheIfNeeded();
};

export const getCachedAudioStream = async (key: string): Promise<Blob | null> => {
  try {
    const db = await openAudioDB();
    const blob = await new Promise<Blob | null>((resolve, reject) => {
      try {
        const transaction = db.transaction("audio-streams", "readonly");
        const store = transaction.objectStore("audio-streams");
        const request = store.get(key);
        request.onsuccess = () => resolve(request.result || null);
        request.onerror = () => reject(request.error);
      } catch (e) {
        reject(e);
      }
    });
    
    if (blob) {
      await updateAudioCacheMetadata(key, blob.size, true);
    }
    return blob;
  } catch (e) {
    console.error("Failed to retrieve cached audio", e);
    return null;
  }
};

export const isAudioStreamCached = async (key: string): Promise<boolean> => {
  try {
    const db = await openAudioDB();
    return new Promise((resolve) => {
      try {
        const transaction = db.transaction("audio-streams", "readonly");
        const store = transaction.objectStore("audio-streams");
        const request = store.getKey(key);
        request.onsuccess = () => resolve(request.result !== undefined);
        request.onerror = () => resolve(false);
      } catch (e) {
        resolve(false);
      }
    });
  } catch (e) {
    return false;
  }
};

export const deleteCachedAudioStream = async (key: string): Promise<void> => {
  const db = await openAudioDB();
  await new Promise<void>((resolve, reject) => {
    try {
      const transaction = db.transaction("audio-streams", "readwrite");
      const store = transaction.objectStore("audio-streams");
      const request = store.delete(key);
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    } catch (e) {
      reject(e);
    }
  });
  
  const meta = getAudioCacheMetadata();
  if (meta[key]) {
    delete meta[key];
    saveAudioCacheMetadata(meta);
  }
};

export const getAllCachedAudioKeys = async (): Promise<string[]> => {
  try {
    const db = await openAudioDB();
    return new Promise((resolve, reject) => {
      try {
        const transaction = db.transaction("audio-streams", "readonly");
        const store = transaction.objectStore("audio-streams");
        const request = store.getAllKeys();
        request.onsuccess = () => resolve((request.result as string[]) || []);
        request.onerror = () => reject(request.error);
      } catch (e) {
        reject(e);
      }
    });
  } catch (e) {
    return [];
  }
};

// Expose on window for easy access
if (typeof window !== "undefined") {
  (window as any).audioCache = {
    cacheAudioStream,
    getCachedAudioStream,
    isAudioStreamCached,
    deleteCachedAudioStream,
    getAllCachedAudioKeys,
    getAudioCacheMetadata,
    syncAudioCacheMetadata,
    pruneAudioCacheIfNeeded
  };
}

