// Utility function to highlight occurrences of query strings within scripture texts
const highlightText = (text: string | null | undefined, query: string): React.ReactNode => {
  if (!text) return "";
  if (!query || !query.trim()) return text;

  const trimmedQuery = query.trim();
  try {
    const escapedQuery = trimmedQuery.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
    const regex = new RegExp(`(${escapedQuery})`, "gi");
    const parts = text.split(regex);

    return (
      <>
        {parts.map((part, index) =>
          regex.test(part) ? (
            <mark
              key={index}
              className="custom-text-highlight font-semibold px-0.5 rounded border"
            >
              {part}
            </mark>
          ) : (
            part
          )
        )}
      </>
    );
  } catch (e) {
    console.error("Highlight regex error:", e);
    return text;
  }
};

