export const getNativeLanguageCode = (bookKey: string, religion: string): string => {
  const r = (religion || "").toLowerCase();
  const k = (bookKey || "").toLowerCase();
  if (r.includes("sikh")) {
    return "pa-IN"; // Punjabi
  }
  if (k.includes("tibetan") || k.includes("tara") || k.includes("gyatpa") || k.includes("kyabdro") || k.includes("buddhist_compassion_mantra")) {
    return "bo-CN"; // Tibetan
  }
  if (k.includes("tamil") || r.includes("tamil")) {
    return "ta-IN"; // Tamil
  }
  if (k.includes("telugu") || r.includes("telugu")) {
    return "te-IN"; // Telugu
  }
  if (k.includes("marathi") || r.includes("marathi")) {
    return "mr-IN"; // Marathi
  }
  if (r.includes("hindu") || k.includes("gita") || k.includes("veda") || k.includes("ramayana") || r.includes("jain") || r.includes("buddh") || k.includes("dhammapada") || k.includes("lalitavistara")) {
    return "sa-IN"; // Sanskrit
  }
  if (r.includes("islam") || k.includes("quran") || k.includes("bukhari")) {
    return "ar-SA"; // Arabic
  }
  if (r.includes("juda") || k.includes("torah") || k.includes("talmud") || r.includes("jewish")) {
    return "he-IL"; // Hebrew
  }
  if (r.includes("taoist") || r.includes("taoism") || k.includes("tao_te_ching") || k.includes("journey_west") || k.includes("chinese") || k.includes("china") || k.includes("analects") || k.includes("confuc")) {
    return "zh-CN"; // Chinese
  }
  if (r.includes("shinto") || k.includes("kojiki") || k.includes("nihon") || k.includes("japanese") || k.includes("japan")) {
    return "ja-JP"; // Japanese
  }
  if (r.includes("russian") || k.includes("russian") || r.includes("orthodox")) {
    return "ru-RU"; // Russian
  }
  if (r.includes("portuguese") || k.includes("portuguese") || r.includes("brazil") || k.includes("brazil")) {
    return "pt-PT"; // Portuguese
  }
  return "en-US";
};

export const buildFullPassageText = (bTitle: string, dName: string, dNum: number | string, intro: string, verses: any[], lang: string, useNativeText = false) => {
  const dicts: Record<string, { introTemplate: string; verseLabel: string }> = {
    "English": {
      introTemplate: "Let's listen to the sacred text of {title}, {divName} {divNum}. Summary of chapter: {intro}.",
      verseLabel: "Verse {num}. "
    },
    "Hindi": {
      introTemplate: "आइए {title}, {divName} {divNum} का पवित्र पाठ सुनें। अध्याय का सारांश: {intro}.",
      verseLabel: "श्लोक {num}: "
    },
    "Spanish": {
      introTemplate: "Escuchemos el texto sagrado de {title}, {divName} {divNum}. Resumen del capítulo: {intro}.",
      verseLabel: "Versículo {num}: "
    },
    "French": {
      introTemplate: "Écoutons le texte sacré de {title}, {divName} {divNum}. Résumé du chapitre: {intro}.",
      verseLabel: "Verset {num}: "
    },
    "German": {
      introTemplate: "Lasst uns den heiligen Text von {title}, {divName} {divNum} hören. Zusammenfassung des Kapitels: {intro}.",
      verseLabel: "Vers {num}: "
    },
    "Japanese": {
      introTemplate: "{title}の{divName}第{divNum}章の聖典を聴きましょう。章の要約：{intro}。",
      verseLabel: "節 {num}: "
    },
    "Chinese": {
      introTemplate: "让我们聆听 {title} {divName} 第 {divNum} 部分的圣典。章节摘要：{intro}。",
      verseLabel: "第 {num} 节："
    },
    "Arabic": {
      introTemplate: "دعونا نستمع إلى النص المقدس لـ {title}، {divName} {divNum}. ملخص الفصل: {intro}.",
      verseLabel: "الآية {num}: "
    },
    "Portuguese": {
      introTemplate: "Vamos ouvir o texto sagrado de {title}, {divName} {divNum}. Resumo do capítulo: {intro}.",
      verseLabel: "Versículo {num}: "
    },
    "Russian": {
      introTemplate: "Давайте послушаем священный текст {title}, {divName} {divNum}. Краткое содержание главы: {intro}.",
      verseLabel: "Стих {num}: "
    },
    "Marathi": {
      introTemplate: "चला {title}, {divName} {divNum} चे पवित्र वाचन ऐकूया. अध्यायाचा सारांश: {intro}.",
      verseLabel: "श्लोक {num}: "
    },
    "Sanskrit": {
      introTemplate: "शृण्वन्तु {title}, {divName} {divNum} इत्यस्य पवित्रग्रन्थस्य पाठम्। अध्यायस्य सारांशः: {intro}.",
      verseLabel: "श्लोकः {num}: "
    },
    "Tamil": {
      introTemplate: "{title}, {divName} {divNum} இன் புனித நூலைக் கேட்போம். அத்தியாயத்தின் சுருக்கம்: {intro}.",
      verseLabel: "வசனம் {num}: "
    },
    "Telugu": {
      introTemplate: "మనం {title}, {divName} {divNum} యొక్క పవిత్ర గ్రంథాన్ని విందాం. అధ్యాయం యొక్క సారాంశం: {intro}.",
      verseLabel: "శ్లోకం {num}: "
    }
  };

  const selected = dicts[lang] || dicts["English"];
  
  const introPart = selected.introTemplate
    .replace("{title}", bTitle)
    .replace("{divName}", dName)
    .replace("{divNum}", String(dNum))
    .replace("{intro}", intro);

  const versesPart = verses
    .map(v => {
      const vlbl = selected.verseLabel.replace("{num}", String(v.number));
      // Speak originalText if useNativeText is true and it's available (otherwise fallback to transliteration or translation)
      const nativeTxt = v.originalText || v.original;
      const contentToSpeak = useNativeText && nativeTxt ? nativeTxt : v.translation;
      return `${vlbl}${contentToSpeak}`;
    })
    .join(" ");

  return `${introPart} ${versesPart}`;
};

