// Simple, fast Levenshtein distance calculation for typo-tolerance
function computedLevenshteinDistance(s1: string, s2: string): number {
  if (s1 === s2) return 0;
  if (!s1.length) return s2.length;
  if (!s2.length) return s1.length;
  
  const matrix: number[][] = Array.from({ length: s1.length + 1 }, () => new Array(s2.length + 1).fill(0));
  
  for (let i = 0; i <= s1.length; i++) matrix[i][0] = i;
  for (let j = 0; j <= s2.length; j++) matrix[0][j] = j;
  
  for (let i = 1; i <= s1.length; i++) {
    for (let j = 1; j <= s2.length; j++) {
      const cost = s1[i - 1] === s2[j - 1] ? 0 : 1;
      matrix[i][j] = Math.min(
        matrix[i - 1][j] + 1, // deletion
        matrix[i][j - 1] + 1, // insertion
        matrix[i - 1][j - 1] + cost // substitution
      );
    }
  }
  return matrix[s1.length][s2.length];
}

// Advanced multi-mode matcher (Exact, Regex, Tokenized, Sub-sequence, and Typo-tolerant Fuzzy)
function matchesSearchWithRegexAndFuzzy(targetTextList: string[], query: string): boolean {
  const qClean = query.trim();
  if (!qClean) return true;

  const queryLower = qClean.toLowerCase();
  const concatenatedTarget = targetTextList.filter(Boolean).join(" ").toLowerCase();

  // 1. Exact or whole-string substring match
  if (concatenatedTarget.includes(queryLower)) {
    return true;
  }

  // 2. Regex-based pattern match
  try {
    const isRegexPattern = /[\\^$.*+?()[\]{}|]/.test(qClean);
    if (isRegexPattern) {
      const regex = new RegExp(qClean, "i");
      if (targetTextList.some(text => text && regex.test(text))) {
        return true;
      }
    }
  } catch (e) {
    // Fall through if invalid regex
  }

  // 3. Shorthand/Fuzzy sub-sequence or token-by-token matching
  const noiseWords = new Set(["in", "the", "on", "of", "and", "a", "at", "for", "to", "vrat", "fast"]);
  const queryTokens = queryLower.split(/\s+/).filter(t => t.length > 0);
  const significantTokens = queryTokens.filter(t => !noiseWords.has(t));
  const tokensToUse = significantTokens.length > 0 ? significantTokens : queryTokens;

  if (tokensToUse.length === 0) return true;

  // Ensure all query tokens are covered by the target text
  const tokenMatchesAll = tokensToUse.every(token => {
    // Standard substring check inside target
    if (concatenatedTarget.includes(token)) return true;

    // Sub-sequence character mapping (e.g., e-k-d-s matching ekadashi)
    if (token.length >= 3) {
      const escapedTokenChars = token.split("").map(c => c.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join(".*");
      try {
        const subseqRegex = new RegExp(escapedTokenChars, "i");
        if (targetTextList.some(text => text && subseqRegex.test(text))) {
          return true;
        }
      } catch (err) {}
    }

    // Levenshtein distance check for typo tolerance on words
    const words = concatenatedTarget.split(/[\s,()\-]+/);
    return words.some(word => {
      if (word.length < 3) return false;
      const distance = computedLevenshteinDistance(word, token);
      const limit = token.length >= 6 ? 2 : 1;
      return distance <= limit;
    });
  });

  return tokenMatchesAll;
}

