const formatChapterTitle = (rawTitle: string): string => {
  if (!rawTitle) return "";
  const openParenIndex = rawTitle.indexOf("(");
  const closeParenIndex = rawTitle.indexOf(")");
  if (openParenIndex !== -1 && closeParenIndex !== -1 && closeParenIndex > openParenIndex) {
    const firstPart = rawTitle.substring(0, openParenIndex).trim();
    const secondPart = rawTitle.substring(openParenIndex + 1, closeParenIndex).trim();
    if (firstPart && secondPart) {
      // Keep prefix (like "Chapter X: ") before the colon if exists
      const colonIndex = firstPart.indexOf(":");
      if (colonIndex !== -1) {
        const prefix = firstPart.substring(0, colonIndex + 1).trim();
        const mainPart = firstPart.substring(colonIndex + 1).trim();
        return `${prefix} ${secondPart} (${mainPart})`;
      }
      return `${secondPart} (${firstPart})`;
    }
  }
  return rawTitle;
};

