  const fadeCleanupRef = useRef<(() => void) | null>(null);
  const isFadingRef = useRef<boolean>(false);
  const prevAudioRef = useRef<HTMLAudioElement | null>(null);

  const fadeAudioVolume = (
    audio: HTMLAudioElement,
    targetVolume: number,
    duration: number,
    onComplete?: () => void
  ): (() => void) => {
    const startVolume = audio.volume;
    const volumeDiff = targetVolume - startVolume;
    if (volumeDiff === 0) {
      if (onComplete) onComplete();
      return () => {};
    }

    const startTime = performance.now();
    let animationFrameId: number;

    const tick = (now: number) => {
      const elapsed = now - startTime;
      const progress = Math.max(0, Math.min(elapsed / duration, 1));
      
      try {
        audio.volume = Math.max(0, Math.min(1, startVolume + volumeDiff * progress));
      } catch (e) {
        console.warn("Error setting audio volume during fade:", e);
      }

      if (progress < 1) {
        animationFrameId = requestAnimationFrame(tick);
      } else {
        try {
          audio.volume = targetVolume;
        } catch (e) {}
        if (onComplete) onComplete();
      }
    };

    animationFrameId = requestAnimationFrame(tick);

    return () => {
      cancelAnimationFrame(animationFrameId);
    };
  };

  // Automatically trigger a 500ms fade-in when a new currentAudio starts playing
  useEffect(() => {
    if (currentAudio && currentAudio !== prevAudioRef.current) {
      prevAudioRef.current = currentAudio;
      currentAudio.volume = 0;
      
      if (fadeCleanupRef.current) fadeCleanupRef.current();
      isFadingRef.current = true;
      fadeCleanupRef.current = fadeAudioVolume(currentAudio, audioVolume, 500, () => {
        isFadingRef.current = false;
      });
    } else if (!currentAudio) {
      prevAudioRef.current = null;
    }
  }, [currentAudio, audioVolume]);

  // Synchronize audio volume, playback rate/speed, and preservesPitch on-the-fly when adjusted
  useEffect(() => {
    if (currentAudio) {
      if (isFadingRef.current) {
        if (fadeCleanupRef.current) {
          fadeCleanupRef.current();
          fadeCleanupRef.current = null;
        }
        isFadingRef.current = false;
      }
      currentAudio.volume = audioVolume;
      try {
        currentAudio.playbackRate = audioSpeed;
      } catch (err) {
        console.warn("Failed to set audio playback rate:", err);
      }
      try {
        (currentAudio as any).preservesPitch = (audioPitch === 1.0);
      } catch (err) {}
    }
  }, [audioVolume, audioSpeed, audioPitch]);

