  const getMatchingVoices = (bcpCode: string, voices: SpeechSynthesisVoice[]) => {
    if (!bcpCode || !voices || voices.length === 0) return [];
    const prefix = bcpCode.split("-")[0].toLowerCase();
    
    // Filter voices matching the language code or prefix or special mappings
    const filtered = voices.filter(v => {
      const vLang = v.lang.toLowerCase().replace("_", "-");
      const vName = v.name.toLowerCase();
      
      // Match exact BCP-47 code
      if (vLang === bcpCode.toLowerCase() || vLang.replace("_", "-") === bcpCode.toLowerCase()) {
        return true;
      }
      
      // Match language prefix
      if (vLang.startsWith(prefix + "-") || vLang === prefix) {
        return true;
      }
      
      // Special phonetic mappings
      if (prefix === "sa" || prefix === "mr") {
        if (vLang === "hi-in" || vLang.startsWith("hi-") || vLang === "hi") {
          return true;
        }
      }
      if (prefix === "ta" || prefix === "te") {
        if (vLang === "hi-in" || vLang.startsWith("hi-") || vLang === "hi" || vLang.startsWith("en-in") || vLang === "en-in") {
          return true;
        }
      }
      if (prefix === "ar" && (vLang.includes("arabic") || vName.includes("arabic"))) {
        return true;
      }
      
      return false;
    });

    return filtered;
  };

