  const renderClickableVerseWords = (text: string, searchQuery?: string) => {
    if (!text) return null;
    const tokens = text.split(/(\s+|[,.:;?!"'()\[\]&“”`‘’—]+)/);
    return tokens.map((token, i) => {
      const isWord = /[a-zA-Z0-9'’]+/.test(token);
      if (isWord) {
        const cleanWord = token.replace(/[^a-zA-Z0-9'’]/g, "");
        const isHighlighted = searchQuery && cleanWord.toLowerCase() === searchQuery.toLowerCase().trim();
        return (
          <span
            key={i}
            className={`cursor-pointer hover:text-amber-400 hover:underline transition-all duration-150 decoration-amber-400/50 decoration-2 select-text ${
              isHighlighted ? "bg-amber-500/30 text-amber-300 px-0.5 rounded-sm" : ""
            }`}
            title={`Analyze word: ${cleanWord}`}
            onClick={(e) => {
              e.stopPropagation();
              handleTermClick(cleanWord);
            }}
          >
            {token}
          </span>
        );
      } else {
        return <span key={i}>{token}</span>;
      }
    });
  };

