  // Reusable helper to convert FirestoreNote database records into clean ReadingNote objects, including artwork gallery notes
  const mapFirebaseNotesToReadingNotes = (firebaseNotes: any[]): ReadingNote[] => {
    return firebaseNotes.map(fn => {
      let rel: ReligionType = "other";
      if (fn.itemKey === "hindu_prayers") {
        rel = (["ayat_al_kursi", "sayyidul_istighfar", "rabbana_duas", "prophet_yunus_dua", "rabbi_zidni_ilman"].includes(fn.portion || "") ? "islam" : ["amazing_grace", "be_thou_my_vision", "holy_holy_holy", "the_lords_prayer", "how_great_thou_art", "peace_prayer_st_francis"].includes(fn.portion || "") ? "christianity" : "hinduism") as ReligionType;
      } else if (fn.itemKey === "art-gallery") {
        const t = (fn.title || "").toLowerCase();
        if (t.includes("krishna") || t.includes("rigveda") || t.includes("yajna") || t.includes("mandala") || t.includes("shiva") || t.includes("vishnu") || t.includes("natataraja")) rel = "hinduism";
        else if (t.includes("buddha") || t.includes("mahavira") || t.includes("jain") || t.includes("zen") || t.includes("shikhara")) rel = "buddhism";
        else if (t.includes("cross") || t.includes("jesus") || t.includes("catacomb") || t.includes("sinai") || t.includes("halo") || t.includes("chapel") || t.includes("monastery") || t.includes("mary") || t.includes("gospel")) rel = "christianity";
        else if (t.includes("quran") || t.includes("mosque") || t.includes("mihrab") || t.includes("calligraphy") || t.includes("kufic") || t.includes("iznik")) rel = "islam";
        else if (t.includes("temple") || t.includes("wall") || t.includes("synagogue") || t.includes("hebrew") || t.includes("torah") || t.includes("menorah")) rel = "judaism";
        else if (t.includes("sikh") || t.includes("golden temple") || t.includes("amritsar") || t.includes("gurdwara") || t.includes("granth")) rel = "other";
        else if (t.includes("parthenon") || t.includes("athens") || t.includes("greece") || t.includes("greek") || t.includes("myth") || t.includes("canvas")) rel = "mythology";
      } else {
        rel = (SCRIPTURE_BOOKS.find(b => b.key === fn.itemKey)?.religion || "other") as ReligionType;
      }
      return {
        id: fn.id || "",
        religion: rel,
        bookKey: fn.itemKey,
        bookTitle: fn.title || "Study Note",
        reference: fn.portion || "General Study",
        noteText: fn.content || "",
        createdTime: fn.createdAt?.seconds ? fn.createdAt.seconds * 1000 : Date.now()
      };
    });
  };

  // Callback to save selected art pieces into the study reflection journal
  const handleSaveArtworkToJournal = async (note: { religion: any; bookKey: string; bookTitle: string; reference: string; noteText: string }): Promise<{ success: boolean; limitReached?: boolean }> => {
    if (!isSupporter && notes.length >= 5) {
      setShowLimitModal("notes");
      return { success: false, limitReached: true };
    }

    if (user) {
      try {
        setReadingLoading(true);
        await createNote(
          "art-gallery",
          note.bookTitle,
          note.noteText,
          note.reference
        );
        const firebaseNotes = await getNotesFromFirestore();
        setNotes(mapFirebaseNotesToReadingNotes(firebaseNotes));
        return { success: true };
      } catch (err) {
        console.error("Failed to save artwork note to Firestore:", err);
        return { success: false };
      } finally {
        setReadingLoading(false);
      }
    } else {
      const newNote: ReadingNote = {
        id: `note-${Date.now()}`,
        religion: note.religion as ReligionType,
        bookKey: "art-gallery",
        bookTitle: note.bookTitle,
        reference: note.reference,
        noteText: note.noteText,
        createdTime: Date.now()
      };
      const updated = [newNote, ...notes];
      saveNotesToStore(updated);
      return { success: true };
    }
  };

  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Load initial notes and synchronize Firebase Auth state listeners
