  // Custom theme helper for headers
  const getTraditionHeaderColor = (religion: ReligionType | undefined) => {
    if (!religion) return "from-amber-600 to-amber-400";
    switch (religion) {
      case "hinduism": return "from-amber-500 to-amber-300";
      case "islam": return "from-emerald-500 to-emerald-300";
      case "christianity": return "from-indigo-500 to-indigo-300";
      case "judaism": return "from-blue-500 to-blue-300";
      case "buddhism": return "from-rose-500 to-rose-300";
      case "jainism": return "from-orange-500 to-orange-300";
      case "sikhism": return "from-yellow-500 to-amber-400";
      case "mythology": return "from-violet-500 to-fuchsia-500";
      case "history": return "from-cyan-500 to-teal-500";
      case "space": return "from-fuchsia-500 to-pink-500";
      default: return "from-slate-500 to-slate-300";
    }
  };

  const getProgressGradient = (religion: ReligionType | undefined) => {
    if (!religion) return "from-amber-600 via-amber-500 to-amber-400";
    switch (religion) {
      case "hinduism": return "from-amber-600 via-amber-500 to-amber-400";
      case "islam": return "from-emerald-600 via-emerald-500 to-emerald-400";
      case "christianity": return "from-indigo-600 via-indigo-500 to-indigo-400";
      case "judaism": return "from-blue-600 via-blue-500 to-blue-400";
      case "buddhism": return "from-rose-600 via-rose-500 to-rose-400";
      case "jainism": return "from-orange-600 via-orange-500 to-orange-400";
      case "sikhism": return "from-yellow-500 via-yellow-400 to-amber-500";
      case "mythology": return "from-violet-600 via-violet-500 to-violet-400";
      case "history": return "from-cyan-600 via-cyan-500 to-cyan-400";
      case "space": return "from-fuchsia-600 via-fuchsia-500 to-fuchsia-400";
      default: return "from-slate-600 via-slate-500 to-slate-400";
    }
  };

  const getReligionBorderAccent = (religion: ReligionType | undefined) => {
    if (!religion) return "border-white/10";
    switch (religion) {
      case "hinduism": return "border-amber-500/20";
      case "islam": return "border-emerald-500/20";
      case "christianity": return "border-indigo-500/20";
      case "judaism": return "border-blue-500/20";
      case "buddhism": return "border-rose-500/20";
      case "jainism": return "border-orange-500/20";
      case "sikhism": return "border-yellow-500/20";
      case "mythology": return "border-violet-500/20";
      case "history": return "border-cyan-500/20";
      case "space": return "border-fuchsia-500/20";
      default: return "border-slate-500/20";
    }
  };

  const getReligionTextAccent = (religion: ReligionType | undefined) => {
    if (!religion) return "text-slate-200";
    switch (religion) {
      case "hinduism": return "text-amber-400";
      case "islam": return "text-emerald-400";
      case "christianity": return "text-indigo-400";
      case "judaism": return "text-blue-400";
      case "buddhism": return "text-rose-400";
      case "jainism": return "text-orange-400";
      case "sikhism": return "text-yellow-400";
      case "mythology": return "text-violet-400";
      case "history": return "text-cyan-400";
      case "space": return "text-fuchsia-400";
      default: return "text-slate-400";
    }
  };

